import{_ as l,o as e,c as i,am as t}from"./chunks/framework._FJXuPhs.js";const u=JSON.parse('{"title":"底层能力","description":"","frontmatter":{"title":"底层能力","excerpt":"Java底层能力——设计模式（GoF 23种）、数据结构和算法","date":"2026-04-23 15:55:52","updated":"2026-05-05 12:00:00"},"headers":[],"relativePath":"底层能力.md","filePath":"底层能力.md","lastUpdated":null}'),h={name:"底层能力.md"};function r(o,a,m,f,n,d){return e(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="设计模式" tabindex="-1">设计模式 <a class="header-anchor" href="#设计模式" aria-label="Permalink to &quot;设计模式&quot;">​</a></h3><p>GoF（四人组）提出的 23 种经典设计模式，按意图分为三大类：创建型（5种）、结构型（7种）、行为型（11种）。</p><ul><li><a href="./.html">Java设计模式</a></li></ul><h4 id="创建型模式" tabindex="-1">创建型模式 <a class="header-anchor" href="#创建型模式" aria-label="Permalink to &quot;创建型模式&quot;">​</a></h4><p>聚焦对象的创建机制，将对象的创建过程与使用方解耦。</p><ul><li><a href="./.html">工厂方法模式</a> — 定义创建对象的接口，将实例化推迟到子类</li><li><a href="./.html">抽象工厂模式</a> — 创建一系列相关对象，保证同族产品兼容性</li><li><a href="./.html">建造者模式</a> — 将复杂对象的构建与表示分离，支持链式调用</li><li><a href="./.html">原型模式</a> — 通过克隆现有对象创建新对象</li><li><a href="./.html">单例模式</a> — 保证类只有一个实例，提供全局访问点</li></ul><h4 id="结构型模式" tabindex="-1">结构型模式 <a class="header-anchor" href="#结构型模式" aria-label="Permalink to &quot;结构型模式&quot;">​</a></h4><p>关注类与对象的组合方式，通过接口转换、功能增强等手段构建灵活的代码结构。</p><ul><li><a href="./.html">适配器模式</a> — 将不兼容的接口转换为客户期望的接口</li><li><a href="./.html">桥接模式</a> — 将抽象与实现分离，使两个维度可独立变化</li><li><a href="./.html">组合模式</a> — 将对象组合成树形结构，统一处理单个对象和组合</li><li><a href="./.html">装饰器模式</a> — 动态给对象添加额外职责，比继承更灵活</li><li><a href="./.html">外观模式</a> — 为复杂子系统提供统一简洁的入口</li><li><a href="./.html">享元模式</a> — 共享内在状态，支持大量细粒度对象</li><li><a href="./.html">代理模式</a> — 为对象提供替代品以控制访问</li></ul><h4 id="行为型模式" tabindex="-1">行为型模式 <a class="header-anchor" href="#行为型模式" aria-label="Permalink to &quot;行为型模式&quot;">​</a></h4><p>关注类或对象之间的交互方式与职责分配。</p><ul><li><a href="./.html">责任链模式</a> — 请求沿处理者链传递，解耦发送者与接收者</li><li><a href="./.html">命令模式</a> — 将请求封装为对象，支持参数化、撤销/重做</li><li><a href="./.html">迭代器模式</a> — 提供统一接口顺序访问聚合对象的元素</li><li><a href="./.html">中介者模式</a> — 用中介对象封装组件间的交互，减少耦合</li><li><a href="./.html">备忘录模式</a> — 捕获并外部化对象状态，用于撤销/恢复</li><li><a href="./.html">观察者模式</a> — 定义一对多依赖，状态改变时自动通知观察者</li><li><a href="./.html">状态模式</a> — 将状态封装为独立类，消除大量条件分支</li><li><a href="./.html">策略模式</a> — 将算法封装为独立策略类，运行时动态切换</li><li><a href="./.html">模板方法模式</a> — 定义算法骨架，延迟步骤到子类</li><li><a href="./.html">访问者模式</a> — 不修改元素类的前提下定义新操作</li></ul><h3 id="数据结构和算法" tabindex="-1">数据结构和算法 <a class="header-anchor" href="#数据结构和算法" aria-label="Permalink to &quot;数据结构和算法&quot;">​</a></h3><ul><li><a href="./.html">Java 数据结构和算法</a></li></ul>',14)])])}const _=l(h,[["render",r]]);export{u as __pageData,_ as default};
